const listarMensajes = `-- name: ListarMensajes :many
SELECT m.id, m.conversacion_id, m.empresa_id, m.seq, m.autor_id, m.texto, m.adjunto_id, m.lat, m.lon, m.creado_en, m.enviado_en, m.hash_contenido, m.eliminado_en, m.created_at, m.updated_at, u.nombre AS autor_nombre, a.estado AS adjunto_estado
FROM mensajeria.chat_mensajes m
JOIN nucleo.usuarios u ON u.id = m.autor_id
LEFT JOIN nucleo.adjuntos a ON a.id = m.adjunto_id
WHERE m.conversacion_id = $1
  AND (($2::boolean AND m.seq > $3::bigint) OR (NOT $2::boolean AND m.seq < $3::bigint))
ORDER BY CASE WHEN $2::boolean THEN m.seq END ASC, CASE WHEN NOT $2::boolean THEN m.seq END DESC
LIMIT $4
`

type ListarMensajesParams struct {
	ConversacionID int64
	Siguientes     bool
	Desde          int64
	Limite         int32
}

type ListarMensajesRow struct {
	MensajeriaChatMensaje MensajeriaChatMensaje
	AutorNombre           string
	AdjuntoEstado         *string
}

// Página de mensajes por seq: siguientes (seq > @desde, ascendente) o anteriores (seq < @desde,
// descendente; el caso de uso la invierte).
func (q *Queries) ListarMensajes(ctx context.Context, arg ListarMensajesParams) ([]ListarMensajesRow, error) {
	rows, err := q.db.Query(ctx, listarMensajes,
		arg.ConversacionID,
		arg.Siguientes,
		arg.Desde,
		arg.Limite,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListarMensajesRow
	for rows.Next() {
		var i ListarMensajesRow
		if err := rows.Scan(
			&i.MensajeriaChatMensaje.ID,
			&i.MensajeriaChatMensaje.ConversacionID,
			&i.MensajeriaChatMensaje.EmpresaID,
			&i.MensajeriaChatMensaje.Seq,
			&i.MensajeriaChatMensaje.AutorID,
			&i.MensajeriaChatMensaje.Texto,
			&i.MensajeriaChatMensaje.AdjuntoID,
			&i.MensajeriaChatMensaje.Lat,
			&i.MensajeriaChatMensaje.Lon,
			&i.MensajeriaChatMensaje.CreadoEn,
			&i.MensajeriaChatMensaje.EnviadoEn,
			&i.MensajeriaChatMensaje.HashContenido,
			&i.MensajeriaChatMensaje.EliminadoEn,
			&i.MensajeriaChatMensaje.CreatedAt,
			&i.MensajeriaChatMensaje.UpdatedAt,
			&i.AutorNombre,
			&i.AdjuntoEstado,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

